    signal z_exp  : signed(7 downto 0) := to_signed(12, 8);
    signal z_valid : std_logic := '0';
    signal z_ready : std_logic;

    signal y_valid, y_last : std_logic;
    signal y_mant : signed(15 downto 0);
    signal b_yexp : signed(7 downto 0);

    -- Deterministic stand-in stimulus, a function of the index and NOTHING
    -- else, so that changing a handshake cannot change one input value.  That
    -- is the whole basis of the cross-skew comparison.  Range is a 12-bit
    -- signed centred on zero, matching `tb_gdn_block`'s m12: full-scale int16
    -- would make every comparison a comparison of clamps.
    function m12(a, b : integer) return signed is
      variable x : unsigned(31 downto 0);
      variable t : unsigned(63 downto 0);
    begin
      t := to_unsigned(a mod 1048576, 32) * to_unsigned(1103515245, 32);
      x := t(31 downto 0) + to_unsigned((b mod 100000) * 12345, 32);
      x := x xor shift_right(x, 15);
      t := x * to_unsigned(668265261, 32);
      x := t(31 downto 0);
      x := x xor shift_right(x, 13);
      return to_signed(to_integer(x(11 downto 0)) - 2048, 16);
    end function;

    -- ------------------------------------------------------------------
    -- B'S y BUFFER, AS A BLOCK RAM RATHER THAN A PROCESS VARIABLE.
    --
    -- This is the SECOND of the two 196,608-bit process variables that stop
    -- `synth_design` finishing RTL Elaboration on the card top.  The first
    -- was `zb`, fixed above; MEASURED 2026-09-15, with `zb` already fixed a
    -- `fk33_card` OOC run still went silent 16 s in and had written nothing
    -- more 44 minutes later, at 9.49 GB and climbing.  Vivado's message for
    -- both is `[Synth 8-3391] ... Failed to dissolve the memory into bits
    -- because the number of bits (196608) is too large`.
    --
    -- WHY A SIGNAL AND NOT A WIDER VARIABLE.  `zb` had to become word-wide
    -- because it is READ DM elements at a time; `yb` is read ONE element per
    -- cycle, so it needs no packing at all.  What it needs is to stop being a
    -- process variable: a variable reads back the same-cycle written value,
    -- which no block RAM implements, so no `ram_style` can apply to one.
    -- `rtl/region_mem.vhd` is this file's working precedent for the shape.
    --
    -- ONE WRITE SITE AND ONE READ SITE, which is what makes it inferrable.
    -- region_mem records the boundary: at THREE read sites Vivado reports
    -- `[Synth 8-6849] Infeasible attribute ram_style = "block"` and falls
    -- back to LUTRAM; at two it recognises the template.  Keep it at one of
    -- each -- a second reader added later silently costs the BRAM.
    --
    -- SIZED VH*DM, NOT A_MAXROWS.  The code's own bound is the assert in
    -- S_RUN, `ycnt = VH*DM` = 4,096; A_MAXROWS is 12,288 and was 3x
    -- oversized here exactly as it was for `zb`.
    --
    -- THE ONE BEHAVIOURAL DIVERGENCE, stated rather than buried.  A variable
    -- write is visible to a read in the SAME cycle and a signal write is not.
    -- Here every write happens on `y_valid` and the only read is in S_DRAIN,
    -- which is entered after `j_busy` falls, so the write stream is complete
    -- before the first read and the two cannot overlap in normal operation.
    -- They can overlap ONLY when a y beat arrives outside the run window --
    -- which already sets `f_lost_b` and already reports an error, because
    -- `y_valid` has no ready and that beat was lost regardless.  So the
    -- divergence is confined to a path this file already treats as a fault,
    -- and it is not reachable by a correct producer.
    -- ------------------------------------------------------------------
    signal ybs : buf_t(0 to VH*DM-1);
    attribute ram_style : string;
    attribute ram_style of ybs : signal is "block";

  begin
    u_ready(U_B) <= rdy;
    u_done(U_B)  <= dn;
    u_err(U_B)   <= '0';
    u_done_epoch((U_B+1)*EPOCH_W-1 downto U_B*EPOCH_W) <= std_logic_vector(ep);
    u_y_exp((U_B+1)*EXP_W-1 downto U_B*EXP_W) <= std_logic_vector(yexp);

    u_gdn : entity work.gdn_block
      generic map(
        KEY_HEADS => KH, VAL_HEADS => VH, DIM => DM, KCONV => KC,
        LAYERS => NLY, CONV_LANES => B_CONV_LANES,
        RECUR_LANES => B_RECUR_LANES, RECUR_SLOTS => B_RECUR_SLOTS,
        L2_LANES => B_L2_LANES, SILU_LANES => B_SILU_LANES,
        RMS_LANES => B_RMS_LANES, STRICT_PRODUCER => STRICT)
      port map(
        clk => clk, rst => rst,
        start => gb_start, layer => b_layer, tk0 => b_tk0, busy => b_busy,
        seq_rst => b_seq_rst,
        cap_req => cap_req, cap_layer => cap_layer, cap_seg => cap_seg,
        cap_exp => cap_exp, cap_ready => cap_ready,
        cv_seg => cv_seg, cv_ren => cv_ren, cv_grp => cv_grp,
        cv_x => cv_x, cv_w => cv_w, cv_cw_exp => cv_cw_exp,
        cv_taken => cv_taken, eseg_taken => eseg_taken,
        sc_head => sc_head,
        sc_al_m => sc_al_m, sc_al_e => sc_al_e,
        sc_dt_m => sc_dt_m, sc_dt_e => sc_dt_e,
        sc_a_m => sc_a_m, sc_a_e => sc_a_e,
        sc_b_m => sc_b_m, sc_b_e => sc_b_e, sc_taken => sc_taken,
        st_ren => st_ren, st_rhead => st_rhead, st_rcol => st_rcol,
        st_rgrp => st_rgrp, st_rdata => st_rdata,
        st_wen => st_wen, st_whead => st_whead, st_wcol => st_wcol,
        st_wgrp => st_wgrp, st_wdata => st_wdata,
        se_rhead => se_rhead, se_rcol => se_rcol, se_rdata => se_rdata,
        se_wen => se_wen, se_whead => se_whead, se_wcol => se_wcol,
        se_wdata => se_wdata,
        w_mant => w_mant, w_exp => w_exp, w_taken => w_taken,
        z_mant => z_mant, z_exp => z_exp,
        z_valid => z_valid, z_ready => z_ready,
        y_valid => y_valid, y_mant => y_mant, y_last => y_last,
        y_exp => b_yexp, done => b_done,
        err_conv => open, err_g => open, err_se => open, y_sat => open,
        dbg_col_ready => open, dbg_col_drop => open);

    -- ---- memories 1 and 2, in one of two forms --------------------------
    -- FALSE: every GDN layer's state on chip.  MEASURED at 5,472 RAMB36
    -- against 672 on the part, and the only reason `gb_real` does not fit.
    -- TRUE: one resident layer in `gdn_state_store`, the rest over AXI.
    -- See the `B_STATE_AXI` generic.
    gen_st_flat : if not B_STATE_AXI generate
    -- ---- memory 1: the recurrent state.  Registered, one cycle. ---------
      st_rdata <= st_rq;
      stmem_p : process(clk) is
        variable a : integer;
        variable stmem : stmem_t := (others => (others => '0'));
      begin
        if rising_edge(clk) then
          -- b_layer is registered at job issue and held for the whole
          -- invocation, so it is stable across every access the block makes.
          --
          -- READ FIRST.  See the declaration comment: with `stmem` a variable
          -- the statement order IS the read-during-write policy, and read-old
          -- is what the signal form gave.  Do not reorder these two blocks.
          if st_ren = '1' then
            a := b_layer*STLY + st_rhead*DM*NBR + st_rcol*NBR + st_rgrp;
            st_rq <= stmem(a);
          end if;
          if st_wen = '1' then
            a := b_layer*STLY + st_whead*DM*NBR + st_wcol*NBR + st_wgrp;
            stmem(a) := st_wdata;
          end if;
        end if;
      end process;

      -- ---- memory 2: the state exponents.  COMBINATIONAL read. -----------
      se_rdata <= semem(b_layer*SELY + se_rhead*DM + se_rcol);
      semem_p : process(clk) is
      begin
        if rising_edge(clk) then
          if se_wen = '1' then
            semem(b_layer*SELY + se_whead*DM + se_wcol) <= se_wdata;
          end if;
        end if;
      end process;
    end generate gen_st_flat;

    gen_st_tier : if B_STATE_AXI generate
      -- The store's st_*/se_* ports are `gdn_block`'s VERBATIM, which is why
      -- this is a drop-in for both processes above and why nothing between
      -- here and `gdn_block` changes shape.
      -- THE FOUR BYTE SIZES ARE DERIVED, NOT DEFAULTED.  `gdn_state_store`'s
      -- defaults (1101824 / 1048576 / 4096 / 49152) are the 9B manifest's
      -- numbers, and they are RIGHT ONLY AT 9B.  Left defaulted, this instance
      -- would address HBM with 9B strides at every other shape -- silently, and
      -- invisibly at 9B, which is the only shape anyone had looked at.
      --
      -- Each is the geometry, and each reproduces the 9B manifest constant:
      --   mant   VH*DM*DM*2      = 32*128*128*2 = 1048576   (stmem: VH*DM*NBR
      --                            entries of RECUR_LANES*16 bits, and
      --                            NBR = DM/RECUR_LANES, so the lanes cancel)
      --   exp    VH*DM           = 32*128       =    4096   (one byte per
      --                                                      head, col)
      --   conv   (KC-1)*QKVN*2   = 3*8192*2     =   49152   (the STORED taps;
      --                            the current column is this token's qkv)
      --   stride mant+exp+conv                  = 1101824
      u_state : entity work.gdn_state_store
        generic map(VAL_HEADS => VH, DIM => DM, RECUR_LANES => B_RECUR_LANES,
                    LAYERS => NLY, KEY_HEADS => KH, KCONV => KC,
                    CONV_LANES => B_CONV_LANES,
                    MANT_BYTES   => BST_MANT_B,
                    EXP_BYTES    => BST_EXP_B,
                    CONV_BYTES   => BST_CONV_B,
                    LAYER_STRIDE => BST_MANT_B + BST_EXP_B + BST_CONV_B,
                    MAXB         => BST_MAXB,
                    CONST_EN     => B_CONST_HBM,
                    CONST_STRIDE => BST_CNST_B,
                    CONST_BYTES  => BST_CNST_B)
        port map(
          clk => clk, rst => rst,
          load_start => js_ld, save_start => js_sv,
          layer => js_layer, state_base => bst_state_base,
          const_base => bst_const_base,
          -- The constants faces.  `cw_seg`/`cw_grp` take the same
          -- unregistered address as the tap face and for the same reason
          -- (see cv_seg below): one-cycle contract, data next cycle.
          cw_seg => cv_seg, cw_grp => cv_grp, cw_w => st_cw_w,
          cw_exp => st_cw_exp,
          sc_dt_m => st_dt_m, sc_a_m => st_a_m, sn_w => st_sn_w,
          sc_dt_e => st_dt_e, sc_a_e => st_a_e, sn_exp => st_sn_e,
          busy => bst_busy_i, done => js_done, err => js_err,
          st_ren => st_ren, st_rhead => st_rhead, st_rcol => st_rcol,
          st_rgrp => st_rgrp, st_rdata => st_rdata,
          st_wen => st_wen, st_whead => st_whead, st_wcol => st_wcol,
          st_wgrp => st_wgrp, st_wdata => st_wdata,
          se_rhead => se_rhead, se_rcol => se_rcol, se_rdata => se_rdata,
          se_wen => se_wen, se_whead => se_whead, se_wcol => se_wcol,
          se_wdata => se_wdata,
          -- THE TAP FACE IS NOW READ, 2026-09-05.  The two producers are NOT
          -- swapped wholesale, because they cannot be: memory 3 supplies
          -- `cv_w`/`cv_cw_exp` as well as the taps and the store carries only
          -- taps.  So the split is by TAP AGE -- the store supplies the KC-1
          -- OLDER columns (`cvdata_p` filled those with zeros), memory 3 keeps
          -- the newest column and both weights.
          --
          -- THE TIMING LINES UP EXACTLY, and that is why the unregistered
          -- `cv_seg`/`cv_grp` are passed and not `cvq_*`.  This port samples
          -- seg/grp on the rising edge and presents `cv_x` the NEXT cycle
          -- (:128); memory 3 is a registered ADDRESS (`cvaddr_p`) feeding a
          -- combinational DATA process (`cvdata_p`), which is the same
          -- one-cycle contract.  Feeding this port the ALREADY-registered
          -- `cvq_*` would land the stored taps one cycle late against the
          -- newest column they are summed with.
          cv_seg => cv_seg, cv_grp => cv_grp, cv_x => st_cv_x,
          cvw_en => js_cvw_en, cvw_seg => js_cvw_seg, cvw_grp => js_cvw_grp,
          cvw_data => js_cvw_data, tok_adv => tok_adv_i,
          r_arvalid => bst_arvalid_i, r_arready => bst_arready,
          r_araddr => bst_araddr_i, r_arlen => bst_arlen_i,
          r_arsize => bst_arsize_i, r_arburst => bst_arburst_i,
          r_rvalid => bst_rvalid, r_rready => bst_rready_i,
          r_rdata => bst_rdata, r_rlast => bst_rlast, r_rresp => bst_rresp,
          w_awvalid => bst_awvalid_i, w_awready => bst_awready,
          w_awaddr => bst_awaddr_i, w_awlen => bst_awlen_i,
          w_awsize => bst_awsize_i, w_awburst => bst_awburst_i,
          w_wvalid => bst_wvalid_i, w_wready => bst_wready,
          w_wdata => bst_wdata_i, w_wstrb => bst_wstrb_i,
          w_wlast => bst_wlast_i,
          w_bvalid => bst_bvalid, w_bready => bst_bready_i,
          w_bresp => bst_bresp);

      u_jobseq : entity work.gdn_job_seq
        generic map(VAL_HEADS => VH, DIM => DM, KEY_HEADS => KH,
                    KCONV => KC, CONV_LANES => B_CONV_LANES, LAYERS => NLY)
        port map(
          clk => clk, rst => rst,
          start => b_start, layer => b_layer,
          busy => js_busy, done => open, err => open,
          ss_load_start => js_ld, ss_save_start => js_sv,
          ss_layer => js_layer, ss_done => js_done, ss_err => js_err,
          cvw_en => js_cvw_en, cvw_seg => js_cvw_seg,
          cvw_grp => js_cvw_grp, cvw_data => js_cvw_data,
          b_start => js_b_start, b_busy => b_busy,
          q_seg => js_q_seg, q_grp => js_q_grp, q_data => js_q_data);

      bst_done_i <= js_done;
      bst_err_i  <= js_err;

      -- THE ONE REGISTER STAGE.  Addressed exactly as `cvdata_p`'s
      -- `t = KC-1` branch addresses this token's column, which is the only
      -- place in this file that already computes it.
      qcol_p : process(clk) is
        variable sbase, ch : integer;
      begin
        if rising_edge(clk) then
          if    js_q_seg = 0 then sbase := 0;
          elsif js_q_seg = 1 then sbase := KH*DM;
          else                    sbase := 2*KH*DM; end if;
          for ln in 0 to B_CONV_LANES-1 loop
            ch := sbase + js_q_grp*B_CONV_LANES + ln;
            if ch < QKVN then
              js_q_data((ln+1)*16-1 downto ln*16) <= std_logic_vector(qkv_b(ch));
            else
              js_q_data((ln+1)*16-1 downto ln*16) <= (others => '0');
            end if;
          end loop;
        end if;
      end process;
    end generate gen_st_tier;

    -- `gdn_block` starts from the sequencer when the tier is on, and the job
    -- FSM waits on the sequencer instead of on `gdn_block` directly.
    gb_start <= js_b_start when B_STATE_AXI else b_start;
    j_busy   <= js_busy    when B_STATE_AXI else b_busy;

    -- ---- memory 3: conv taps and weights.  Registered ADDRESS, ---------
    -- combinational DATA, which is what a BRAM with a registered address
    -- port gives and what the port comment demands.
    cvaddr_p : process(clk) is
    begin
      if rising_edge(clk) then
        cvq_seg <= cv_seg;
        cvq_grp <= cv_grp;
      end if;
    end process;

    -- ONE pulse per token: the `tok_done`/`tok_ack` handshake, which is the
    -- same edge `tokp` uses to advance `tok_pos`, so the store's rotation and
    -- this file's sequence position cannot drift apart.  Held at '0' when the
    -- state tier is absent, where nothing reads it.
    tok_adv_i <= tok_done_i and tok_ack when B_STATE_AXI else '0';

    -- `st_cv_x` IS in the sensitivity list: it is read below whenever
    -- B_STATE_AXI, and a combinational process that reads a signal it does not
    -- list simulates differently from the hardware it synthesises to.
    cvdata_p : process(cvq_seg, cvq_grp, qkv_b, st_cv_x, st_cw_w) is
      variable xv, wv : std_logic_vector(KC*B_CONV_LANES*16-1 downto 0);
      variable b, ch, sbase : integer;
    begin
      -- The conv WEIGHTS are learned constants in every configuration.
      -- With B_CONST_HBM they are the MODEL'S, read off the store's weight
      -- face at the same (seg, grp) and in the same bit order this loop
      -- builds: tap t lane ln at (t*B_CONV_LANES + ln)*16, t = KC-1 newest.
      if B_CONST_HBM then
        wv := st_cw_w;
      else
        for t in 0 to KC-1 loop
          for ln in 0 to B_CONV_LANES-1 loop
            b := (t*B_CONV_LANES + ln)*16;
            wv(b+15 downto b) :=
              std_logic_vector(m12(cvq_seg*65537 + cvq_grp*13, t*101 + ln + 5));
          end loop;
        end loop;
      end if;

      if B_SRC_REAL then
        -- q | k | v in that channel order, the same two boundaries
        -- `seq_opdec`'s MSEG mechanism and this file's `last_seg` use.
        if    cvq_seg = 0 then sbase := 0;
        elsif cvq_seg = 1 then sbase := KH*DM;
        else                   sbase := 2*KH*DM; end if;
        for t in 0 to KC-1 loop
          for ln in 0 to B_CONV_LANES-1 loop
            b := (t*B_CONV_LANES + ln)*16;
            if t = KC-1 then
              ch := sbase + cvq_grp*B_CONV_LANES + ln;
              if ch < QKVN then
                xv(b+15 downto b) := std_logic_vector(qkv_b(ch));
              else
                xv(b+15 downto b) := (others => '0');
              end if;
            elsif B_STATE_AXI then
              -- THE STORED HISTORY, 2026-09-05.  `gdn_state_store` holds the
              -- previous KC-1 columns (49,152 B per layer) and presents them
              -- OLDEST FIRST on `cv_x`, with the current column excluded --
              -- which is exactly this loop's `t = 0 .. KC-2`, same `b`, same
              -- `B_CONV_LANES`.  So the index is shared, not converted.
              xv(b+15 downto b) := st_cv_x(b+15 downto b);
            else
              -- Older than the first token, and with no state tier there is
              -- nowhere else for them to come from.  `gdn_exp_capture`'s
              -- tvalid mask excludes these AT TOKEN 0; from token 1 it does
              -- NOT, which is what the `tok_pos` assert below still refuses.
              xv(b+15 downto b) := (others => '0');
            end if;
          end loop;
        end loop;
      else
        for t in 0 to KC-1 loop
          for ln in 0 to B_CONV_LANES-1 loop
            b := (t*B_CONV_LANES + ln)*16;
            xv(b+15 downto b) :=
              std_logic_vector(m12(cvq_seg*104729 + cvq_grp*31, t*17 + ln));
          end loop;
        end loop;
      end if;
      cv_x <= xv;
      cv_w <= wv;
    end process;

    -- Per SEGMENT, published one cycle behind `cv_seg` like a register file.
    cvsq : process(clk) is
    begin
      if rising_edge(clk) then
        if B_CONST_HBM then
          -- The packer's per-segment exponent for this layer, a level from
          -- the end of the load phase; registered here like the stand-in so
          -- gdn_block's cv_seg-before-cv_cw_exp ordering is unchanged.
          cv_cw_exp <= signed(st_cw_exp(cv_seg*8+7 downto cv_seg*8));
        else
          cv_cw_exp <= to_signed(12 + cv_seg, 8);
        end if;
      end if;
    end process;

    -- ---- memory 4: the four scalars.  Registered, one cycle. -----------
    scq : process(clk) is
    begin
      if rising_edge(clk) then
        sc_head_q <= sc_head;
      end if;
    end process;

    scdrv : process(sc_head_q, alp_b, bet_b, alp_e, bet_e,
                    st_dt_m, st_a_m, st_dt_e, st_a_e) is
      variable ix : integer;
    begin
      ix      := sc_head_q;
      -- ssm_dt_bias and ssm_a are LEARNED per-head weights.  They have no
      -- region and their scale does not move with the token.
      if B_CONST_HBM then
        -- The model's, from the store's scalar block; head ix at ix*16.
        sc_dt_m <= signed(st_dt_m(ix*16+15 downto ix*16));
        sc_a_m  <= signed(st_a_m(ix*16+15 downto ix*16));
        sc_dt_e <= st_dt_e;
        sc_a_e  <= st_a_e;
      else
        sc_dt_m <= m12(ix*31 + 2, 3);
        -- ssm_a is -exp(A_log), so `a` is always <= 0 and the decay never
        -- amplifies.  A positive one would exercise a case the model cannot
        -- produce.
        sc_a_m  <= -abs(m12(ix*31 + 3, 4));
        sc_dt_e <= to_signed(12, 8);
        sc_a_e  <= to_signed(12, 8);
      end if;
      if B_SRC_REAL then
        -- alpha and beta ARE per-token activations: subsystem A projects them
        -- into R_ALPHA and R_BETA, one element per value head, which is
        -- exactly `sc_head`'s index.
        sc_al_m <= alp_b(ix);
        sc_b_m  <= bet_b(ix);
        sc_al_e <= alp_e;
        sc_b_e  <= bet_e;
      else
        sc_al_m <= m12(ix*31 + 1, 2);
        sc_b_m  <= m12(ix*31 + 4, 5);
        sc_al_e <= to_signed(12, 8);
        sc_b_e  <= to_signed(12, 8);
      end if;
    end process;

    -- ---- memory 5: the ssm_norm weight.  A level. ----------------------
    wdrv : process(all) is
    begin
      if B_CONST_HBM then
        -- The model's ssm_norm weight and its exponent, from the store.
        w_mant <= st_sn_w;
        w_exp  <= to_integer(st_sn_e);
      else
        for j in 0 to DM-1 loop
          w_mant((j+1)*16-1 downto j*16) <= std_logic_vector(m12(4242, j));
        end loop;
        w_exp <= 12;
      end if;
    end process;

    -- ---- the adapter, the z producer and the y sink --------------------
    bp : process(clk) is
      type st_t is (S_IDLE, S_QRD, S_BRD, S_ARD, S_ZRD, S_CAPW, S_CAPR,
                    S_GO, S_ARM, S_RUN, S_DRAIN, S_DONE);
      variable st : st_t := S_IDLE;
      -- `zb` IS READ DM ELEMENTS AT A TIME, SO IT IS STORED DM-WIDE.
      --
      -- It used to be `buf_t(0 to A_MAXROWS-1)` -- 12,288 x 16 = 196,608 bits
      -- of PROCESS VARIABLE -- read below as
      --     for j in 0 to DM-1 loop ... zb(h*DM + j) ... end loop;
      -- i.e. a DM-way PARALLEL COMBINATIONAL read at an arbitrary base.  That
      -- is not a memory pattern under any `ram_style`, and MEASURED 2026-09-14
      -- it is what stopped the card top elaborating at all:
      --   ERROR: [Synth 8-3391] Unable to infer a block/distributed RAM for
      --   'gb_real.bp.zb_reg' ... number of bits (196608) is too large
      -- `synth_design -rtl -top fk33_llama_top` never finished RTL Elaboration
      -- for 60 h; with A_MAXROWS forced to 512 it finished in 4 minutes with
      -- zero errors.  See
      -- docs/debugging/2026-09-14_the-wall-is-a-3d-ram-vivado-warned-about.md.
      --
      -- THE REWRITE IS AN IDENTITY, not an approximation:
      --   * S_ZRD writes indices 0 .. VH*DM-1 STRICTLY SEQUENTIALLY (`k` rises
      --     by one per cycle and the write is `zb(k-2)`), so staging DM
      --     elements and committing one word cannot reorder anything.
      --   * the ONLY read is `zb(h*DM + j)` for all j in 0..DM-1, which is
      --     exactly word `h`.
      --   * every write completes in S_ZRD before the z handshake, which runs
      --     only in S_GO/S_ARM/S_RUN, so no word is read before it is whole.
      -- A_MAXROWS was also 3x oversized here: the code's own bound is
      -- `k < VH*DM` = 4,096, against A_MAXROWS = 12,288.
      type zw_t is array (0 to VH-1) of std_logic_vector(DM*16-1 downto 0);
      variable zbw   : zw_t;
      variable zstg  : std_logic_vector(DM*16-1 downto 0) := (others => '0');
      variable zlane : natural range 0 to DM-1 := 0;
      variable zword : natural range 0 to VH-1 := 0;
      -- `yb` is gone; it is the signal `ybs` declared above this process.
      variable j_dst, j_rows, j_lay : natural := 0;
      variable k, seg, h, ycnt : natural := 0;
      variable zi : natural := 0;
    begin
      if rising_edge(clk) then
        ur_en(U_B) <= '0';
        uw_en(U_B) <= '0';
        cap_req    <= '0';
        b_start    <= '0';

        if rst = '1' then
          st := S_IDLE; rdy <= '1'; dn <= '0'; z_valid <= '0';
        else
          if job_issue = '1' and to_integer(job_unit) = U_B then
            j_dst  := to_integer(job_dst(6 downto 0));
            j_rows := to_integer(job_n_rows(15 downto 0));
            j_lay  := to_integer(job_ordinal);
            -- `job_ordinal` IS the GDN layer ordinal, 0 .. gdn_layers-1.  It
            -- is taken, not derived.  D spec 4.1 and 6.1: the field is
            -- per-KIND ("B: 0..47, C: 0..15" at the 27B shape), the host
            -- generator computes `gdn_ord(i) = i - (i+1)/attn_interval`, and
            -- `rtl/seq_top_skel.vhd:403` wires the latched ordinal straight
            -- into `b_w_sel` with no arithmetic at all -- which is the point
            -- of the field and the reason spec 4.1 says D does not compute
            -- these (a divide by a generic `attn_interval` is not free).
            --
            -- THIS LINE USED TO RE-DERIVE THE ORDINAL FROM A BLOCK INDEX, and
            -- that was defect ORD-1: the only generator that agreed was
            -- `sim/llama_sched_pkg.vhd`, which stamped `blk mod 64`, while
            -- `sim/seq_tbl_pkg.vhd` and `tools/gen_layer_program.py` both
            -- stamp the per-kind ordinal the spec defines.  MEASURED at the
            -- 9B shape: driving the manifest-stamped program into the old
            -- code addressed the wrong layer on 29 of 32 blocks.  See
            -- `docs/debugging/2026-08-29_ordinal-two-meanings.md`.
            --
            -- SIMULATION ONLY, and BEFORE the assignment on purpose: the
            -- signal's own range would abort first and print only
            -- "bound check failure", which says nothing about why.  A VHDL
            -- integer range is a WIDTH in synthesis and not a check, so
            -- nothing here or on the card catches this on silicon -- see the
            -- write-up's section on what -1 actually does.
            assert j_lay < NLY
              report "llama_top: unit B was issued ordinal "
                   & integer'image(j_lay) & " but this shape has only "
                   & integer'image(NLY) & " GDN layers.  `ordinal` is the "
                   & "PER-KIND layer index (D spec 4.1), not the block index."
              severity failure;
            b_layer  <= j_lay;
            ep       <= job_epoch;
            rdy      <= '0';
            k        := 0;
            ycnt     := 0;
            seg      := 0;
            h        := 0;
            zi       := 0;
            if B_SRC_REAL then
              st := S_QRD;
              b_exp_region <= to_unsigned(R_QKV, 8);
              b_exp_seg    <= "00";
            else
              st := S_ZRD;
              b_exp_region <= to_unsigned(R_Z, 8);
              b_exp_seg    <= "00";
            end if;
          end if;

          -- The un-refusable y stream.  Outside the FSM: a beat that arrives
          -- where it was not expected must still be ACCEPTED, then reported.
          if y_valid = '1' then
            if st /= S_RUN then
              f_lost_b <= '1';
              report "llama_top: unit B emitted a y element outside its run "
                   & "window.  y_valid has no ready, so this element is LOST."
                severity error;
            end if;
            if ycnt < VH*DM then ybs(ycnt) <= y_mant; end if;
            ycnt := ycnt + 1;
          end if;

          case st is
            when S_IDLE => null;

            -- ---- B_SRC_REAL only: the three activation prefetches --------
            -- Same two-edge region-read discipline as every other adapter in
            -- this file: the address is registered here and the memory
            -- registers the data, so an address issued at k is consumed at
            -- k-2 and the loop runs to n+1 to drain.  Consuming at k-1 is
            -- defect 3 and it is silent.
            when S_QRD =>
              if k < QKVN then
                ur_en(U_B)   <= '1';
                ur_reg(U_B)  <= R_QKV;
                ur_addr(U_B) <= k;
              end if;
              if k >= 2 then qkv_b(k-2) <= el_rdata; end if;
              if k = QKVN+1 then
                k := 0;
                b_exp_region <= to_unsigned(R_BETA, 8);
                st := S_BRD;
              else
                k := k + 1;
              end if;

            when S_BRD =>
              if k < VH then
                ur_en(U_B)   <= '1';
                ur_reg(U_B)  <= R_BETA;
                ur_addr(U_B) <= k;
              end if;
              if k >= 2 then bet_b(k-2) <= el_rdata; end if;
              if k = VH+1 then
                assert exp_rd_valid = '1'
                  report "llama_top: unit B read R_BETA's exponent before "
                       & "anything captured it."
                  severity error;
                bet_e <= resize(exp_rd_data, 8);
                k := 0;
                b_exp_region <= to_unsigned(R_ALPHA, 8);
                st := S_ARD;
              else
                k := k + 1;
              end if;

            when S_ARD =>
              if k < VH then
                ur_en(U_B)   <= '1';
                ur_reg(U_B)  <= R_ALPHA;
                ur_addr(U_B) <= k;
              end if;
              if k >= 2 then alp_b(k-2) <= el_rdata; end if;
              if k = VH+1 then
                assert exp_rd_valid = '1'
                  report "llama_top: unit B read R_ALPHA's exponent before "
                       & "anything captured it."
                  severity error;
                alp_e <= resize(exp_rd_data, 8);
                k := 0;
                b_exp_region <= to_unsigned(R_Z, 8);
                st := S_ZRD;
              else
                k := k + 1;
              end if;

            -- Read the whole gate region into a buffer BEFORE starting, so
            -- the z handshake never has to wait on a region read while the
            -- block is running.
            when S_ZRD =>
              -- PATH-INDEPENDENT CURSOR RESET, and the reason it is written
              -- this way.  There are TWO transitions into S_ZRD -- the
              -- `not B_SRC_REAL` bypass and the alpha path after S_ARD -- and
              -- the first version of this fix reset the cursors on only one of
              -- them.  MEASURED: `tb_llama_top` went from PASS 8 to FAIL 6 with
              -- `R_X(0)` off by 29, because the second sweep entered with a
              -- saturated `zword` and every element landed in the last word.
              -- Both paths set `k := 0` before entering, so keying the reset off
              -- `k = 0` cannot be missed by a future third path.
              if k = 0 then zlane := 0; zword := 0; end if;
              if k < VH*DM then
                ur_en(U_B)   <= '1';
                ur_reg(U_B)  <= R_Z;
                ur_addr(U_B) <= k;
              end if;
              -- Was `zb(k-2) := el_rdata`.  Same element, same order; the
              -- word is committed when its last lane arrives.
              if k >= 2 then
                zstg((zlane+1)*16-1 downto zlane*16) :=
                  std_logic_vector(el_rdata);
                if zlane = DM-1 then
                  zbw(zword) := zstg;
                  zlane := 0;
                  -- NO CLAMP.  `zword` is `natural range 0 to VH-1`, so an
                  -- overrun is a loud range error in simulation.  The first
                  -- version clamped here, which converted exactly that fault
                  -- into silent corruption and cost a full bench cycle to find.
                  if zword /= VH-1 then zword := zword + 1; end if;
                else
                  zlane := zlane + 1;
                end if;
              end if;
              if k = VH*DM+1 then
                z_exp <= resize(exp_rd_data, 8);
                k := 0;
                st := S_CAPW;
              else
                k := k + 1;
              end if;

            -- One capture per q/k/v segment, carrying A's y_exp for that
            -- projection.  Hold-until-ready on both sides: wait for
            -- cap_ready with cap_req low, pulse for one cycle, then wait for
            -- cap_ready again before the next.
            when S_CAPW =>
              if cap_ready = '1' and cap_req = '0' then
                cap_layer <= b_layer;
                cap_seg   <= seg;
                cap_exp   <= qkv_exp(seg);
                cap_req   <= '1';
                st        := S_CAPR;
              end if;

            when S_CAPR =>
              if cap_ready = '1' then
                if seg = 2 then st := S_GO; else seg := seg + 1; st := S_CAPW; end if;
              end if;

            when S_GO =>
              b_start <= '1';
              -- `tk0` IS THE SEQUENCE POSITION, NOT A CONSTANT.  This line
              -- read `b_tk0 <= '1'` -- "one token only; there is no token
              -- loop yet" -- and the premise expired: `sim/tb_llama_top_seq`
              -- runs NTOK = 3 and is a gate row.  Driving it high at every
              -- token makes `rtl/gdn_recur_pipe.vhd`'s TK0_ED mask the state
              -- read on EVERY token, so the recurrent state is written and
              -- never read and subsystem B -- a RECURRENT architecture -- is
              -- computed as if every token were token 0.
              --
              -- `tok_pos` is the only sequence position this file has: reset
              -- clears it and the `tok_done`/`tok_ack` handshake advances it,
              -- so it is stable for the whole of a token and `tok_pos = 0` is
              -- exactly the first token of a sequence.  It is the same source
              -- subsystem C's `c_cpos` takes, so B and C cannot disagree about
              -- which token this is.
              --
              -- MEASURED cost at the `seq` capture: this line ALONE was
              -- 60 to 75 of 128 mantissas per `R_Y` seam wrong at tokens 1
              -- and 2; with the per-token `b_seq_rst` below it, 65 to 88.
              -- docs/debugging/2026-08-29_btop1-b-recurrence.md.
              if tok_pos = 0 then b_tk0 <= '1'; else b_tk0 <= '0'; end if;

              -- THE CONV TAP HISTORY IS THE OTHER HALF, and under B_SRC_REAL
              -- this file does not hold one.  `cvdata_p` writes ZERO into
              -- every tap but the newest (see the branch above), which was
              -- inert while `b_seq_rst` fired every token and `tvalid` masked
              -- those slots.  With the per-SEQUENCE reset below, `tvalid`
              -- opens tap KCONV-2 at token 1 and KCONV-3 at token 2, and a
              -- zero mantissa carrying a REAL captured exponent is then summed
              -- as if it were an activation.  Holding the history is a new
              -- (KCONV-1) x qkv_dim buffer -- 3 x 8,192 words at the 9B shape
              -- -- and B_SRC_REAL cannot be run today for an unrelated reason
              -- (:52-58: it makes R_ALPHA physically impossible), so this
              -- REFUSES rather than producing a plausible wrong number.
              --
              -- SIMULATION ONLY, like the `j_lay` guard above: a VHDL
              -- severity is not a check in synthesis.  B_SRC_REAL is a bench
              -- switch and has no meaning on the card.
              -- NARROWED 2026-09-05, from `B_SRC_REAL and tok_pos > 0`.  The
              -- history now EXISTS when the state tier is on: `gdn_state_store`
              -- holds the previous KC-1 columns and `cvdata_p` reads them off
              -- `st_cv_x` instead of writing zeros.  So the refusal applies to
              -- exactly the case that is still unfixed -- B_SRC_REAL WITHOUT
              -- the tier, where there is nowhere for the history to live.
              --
              -- THIS IS NOT A CLAIM THAT THE WIRED PATH IS CORRECT.  It is a
              -- claim that it is no longer STRUCTURALLY absent.  Correctness
              -- at tok_pos > 0 is an oracle question, not an assert question.
              assert not (B_SRC_REAL and not B_STATE_AXI and tok_pos > 0)
                report "llama_top: B_SRC_REAL is true at token "
                     & integer'image(tok_pos) & " with B_STATE_AXI false, so "
                     & "this file holds no conv tap HISTORY -- every tap but "
                     & "the newest is zero (cvdata_p).  From token 1 "
                     & "gdn_exp_capture's tvalid marks those slots VALID, so "
                     & "the conv would sum zeros at a real exponent.  Refusing "
                     & "rather than producing a plausible wrong number.  Turn "
                     & "B_STATE_AXI on: the store carries the history."
                severity failure;

              -- AND THE WIRED PATH IS VERIFIED, 2026-09-05, against an
              -- INDEPENDENT model and with the control that gives the result
              -- meaning.  `tools/ref9b/gdn_oracle.py --b-src-real`, which
              -- reaches the history by CAPTURE KEY (`R_QKV.*` at an earlier
              -- token) and derives tap `j` as the column of token
              -- `t-(KCONV-1-j)` from the DEFINITION of a causal convolution,
              -- never consulting the store or the rotation:
              --
              --   stored taps  9 of 9 R_Y seams match the model BIT FOR BIT
              --   zero-fill    3 of 9 -- and the 3 are exactly the TOKEN 0
              --                seams, where no history exists so both agree.
              --                All six token-1/2 seams differ, 124-128 of 128
              --                mantissas each.
              --
              -- So the oracle discriminates exactly where history exists and
              -- nowhere else, which is what makes 9 of 9 evidence rather than
              -- an insensitive check.  BLOCKS=4, NTOK=3, real weights.
              --
              -- NOT yet shown: 8/16/32 blocks, and a LAYER boundary as opposed
              -- to a token boundary.  The refusal above still stands for
              -- B_SRC_REAL without the tier.
              st      := S_ARM;

            -- `busy` does not rise on the same edge as `start`, so waiting
            -- for it to FALL without first seeing it RISE completes instantly.
            when S_ARM =>
              if j_busy = '1' then st := S_RUN; end if;

            when S_RUN =>
              -- COMPLETION IS `busy` FALLING.  `done` is a one-cycle pulse
              -- with no ack and this adapter never reads it.
              if j_busy = '0' then
                k    := 0;
                yexp <= resize(b_yexp, EXP_W);
                assert ycnt = VH*DM
                  report "llama_top: unit B produced " & integer'image(ycnt)
                       & " y elements, expected " & integer'image(VH*DM)
                       & ".  An un-stallable stream lost or gained beats."
                  severity error;
                if j_dst < NREGION then st := S_DRAIN; else st := S_DONE; end if;
              end if;

            when S_DRAIN =>
              uw_en(U_B)   <= '1';
              uw_reg(U_B)  <= j_dst;
              uw_addr(U_B) <= k;
              if k < VH*DM then uw_data(U_B) <= ybs(k); end if;
              if k = j_rows-1 then st := S_DONE; else k := k + 1; end if;

            when S_DONE =>
              dn <= '1';
              if u_ack(U_B) = '1' then
                dn  <= '0';
                rdy <= '1';
                st  := S_IDLE;
              end if;
          end case;

          -- The z handshake, one offer per value head, running alongside.
          if st = S_RUN or st = S_ARM or st = S_GO then
            if z_valid = '0' and h < VH then
              -- Was a DM-way parallel read `zb(h*DM + j)` for all j.  Word
              -- `h` holds exactly those DM elements in the same bit order.
              z_mant <= zbw(h);
              z_valid <= '1';
            elsif z_valid = '1' and z_ready = '1' then
              z_valid <= '0';
              h := h + 1;
            end if;
          else
            z_valid <= '0';
          end if;
        end if;
      end if;
    end process;
  end generate;
end architecture;
